const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Obolon district, Kyiv, Ukraine (approximate center point with a 5km buffer)
  const obolonPoint = ee.Geometry.Point(30.499, 50.507);
  const obolon = obolonPoint.buffer(5000); // 5 km buffer

  const startDateMarch = '2022-03-01';
  const endDateMarch = '2022-03-31';
  const startDateMay = '2022-05-01';
  const endDateMay = '2022-05-31';

  // 2. Data Acquisition
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG');

  const collectionMarch = viirsCollection
    .filterDate(startDateMarch, endDateMarch)
    .filterBounds(obolon)
    .select('avg_rad');

  const collectionMay = viirsCollection
    .filterDate(startDateMay, endDateMay)
    .filterBounds(obolon)
    .select('avg_rad');

  // Check collection sizes
  const sizeMarch = await collectionMarch.size().getInfo();
  const sizeMay = await collectionMay.size().getInfo();

  if (sizeMarch === 0 || sizeMay === 0) {
    console.log(`March 2022 Images: ${sizeMarch}`);
    console.log(`May 2022 Images: ${sizeMay}`);
    console.log('C1: Empty Collection (No images found for one or both periods).');
    return;
  }

  // Take the first image of each month (monthly composites usually have one image per month)
  const imageMarch = collectionMarch.first();
  const imageMay = collectionMay.first();

  // 3. Processing & Calculation
  const scale = 1000; // Resolution in meters for reduceRegion

  // Calculate mean nighttime lights for March
  const statsMarch = await imageMarch.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: obolon,
    scale: scale,
    maxPixels: 1e9,
  }).get('avg_rad').getInfo();

  // Calculate mean nighttime lights for May
  const statsMay = await imageMay.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: obolon,
    scale: scale,
    maxPixels: 1e9,
  }).get('avg_rad').getInfo();

  // Validate pixel counts (using a small sample to check for C2, though less common for monthly composites)
  const pixelCountMarch = await imageMarch.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: obolon,
    scale: scale,
    maxPixels: 1e9,
  }).get('avg_rad').getInfo();

  const pixelCountMay = await imageMay.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: obolon,
    scale: scale,
    maxPixels: 1e9,
  }).get('avg_rad').getInfo();


  if (pixelCountMarch === 0 || pixelCountMay === 0) {
    console.log(`March 2022 Valid Pixels: ${pixelCountMarch}`);
    console.log(`May 2022 Valid Pixels: ${pixelCountMay}`);
    console.log('C2: No Valid Pixels (Images exist, but after processing, 0 pixels remain in geometry).');
    return;
  }

  // 4. Validation & Final Answer
  if (statsMarch === null || statsMay === null || isNaN(statsMarch) || isNaN(statsMay)) {
    console.log(`March 2022 Mean Radiance: ${statsMarch}`);
    console.log(`May 2022 Mean Radiance: ${statsMay}`);
    console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
    return;
  }

  console.log(`March 2022 Mean Radiance (nW/cm^2/sr): ${statsMarch.toFixed(4)} (Pixels: ${pixelCountMarch})`);
  console.log(`May 2022 Mean Radiance (nW/cm^2/sr): ${statsMay.toFixed(4)} (Pixels: ${pixelCountMay})`);

  if (statsMay < statsMarch) {
    console.log('A: Yes'); // Nighttime lights decreased
  } else {
    console.log('B: No'); // Nighttime lights did not decrease
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
